import { test, expect } from '@playwright/test';

test.describe('Payment Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/checkout');
  });

  test('should display error for invalid card details', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '1234 5678 9012 3456');
    await page.fill(getByLabel('Expiry Date'), '12/23');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Complete Purchase' }));

    const errorMessage = await page.getByText('Invalid card details. Please try again.');
    await expect(errorMessage).toBeVisible();
  });

  test('should complete purchase with valid card details', async ({ page }) => {
    await page.fill(getByLabel('Card Number'), '4111 1111 1111 1111');
    await page.fill(getByLabel('Expiry Date'), '12/25');
    await page.fill(getByLabel('CVC'), '123');
    await page.click(getByRole('button', { name: 'Complete Purchase' }));

    const successMessage = await page.getByText('Thank you for your purchase!');
    await expect(successMessage).toBeVisible();
  });
});
